-- =====================================================================
-- Coaching Academy Video Course Platform: initial schema
-- Target: Supabase (PostgreSQL). Save as:
--   supabase/migrations/initial_schema.sql
--
-- Conventions
--   * ids are uuid, generated by the database
--   * timestamps are timestamptz (UTC)
--   * money is integer paise, durations are integer seconds
--   * status columns are text with check constraints
--   * foreign keys to financial or historical rows use ON DELETE RESTRICT
--
-- Rules the database CANNOT enforce (the backend must):
--   * refund amount must not exceed the payment amount
--   * refund_requests.course_id must match the payment's course
--   * refund_requests.user_id must match the payment's user
--   * payments.amount must equal the course price at order time
--   * a course may be published only with a teacher, thumbnail, and
--     at least one ready lecture
--   * payment status moves forward only
--     (created -> captured | failed, captured -> refunded)
--   * a refund request must be made at or before the payment's
--     refund_eligible_until
--
-- First admin (run by hand after that person has signed in with Google):
--   update public.profiles set role = 'admin' where email = 'you@example.com';
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. Shared trigger function: keep updated_at fresh
-- ---------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;


-- ---------------------------------------------------------------------
-- 1. profiles
-- ---------------------------------------------------------------------
create table public.profiles (
  id           uuid        primary key
                           references auth.users (id) on delete restrict,
  user_name    text        not null
                           constraint profiles_user_name_len
                           check (char_length(user_name) between 1 and 100),
  email        text        not null
                           constraint profiles_email_key unique,
  phone_number text
                           constraint profiles_phone_len
                           check (phone_number is null
                                  or char_length(phone_number) between 7 and 20),
  role         text        not null default 'student'
                           constraint profiles_role_check
                           check (role in ('student', 'admin')),
  is_blocked   boolean     not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create trigger trg_profiles_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 2. teachers (display-only records, no login)
-- ---------------------------------------------------------------------
create table public.teachers (
  id           uuid        primary key default gen_random_uuid(),
  name         text        not null
                           constraint teachers_name_not_blank
                           check (char_length(btrim(name)) > 0),
  email        text,       -- admin-only, never returned to students
  phone_number text,       -- admin-only, never returned to students
  bio          text,
  photo_url    text,
  is_active    boolean     not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create trigger trg_teachers_updated_at
  before update on public.teachers
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 3. courses
-- ---------------------------------------------------------------------
create table public.courses (
  id            uuid        primary key default gen_random_uuid(),
  name          text        not null
                            constraint courses_name_len
                            check (char_length(name) between 3 and 150),
  slug          text        not null
                            constraint courses_slug_key unique
                            constraint courses_slug_format
                            check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  description   text        not null,
  thumbnail_url text,
  is_published  boolean     not null default false,
  price         integer     not null
                            constraint courses_price_positive check (price > 0),
  teacher_id    uuid        not null
                            references public.teachers (id) on delete restrict,
  lecture_count integer     not null default 0
                            constraint courses_lecture_count_nonneg
                            check (lecture_count >= 0),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index idx_courses_teacher_id
  on public.courses (teacher_id);

create index idx_courses_published_created
  on public.courses (is_published, created_at desc);

create trigger trg_courses_updated_at
  before update on public.courses
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 4. lectures
-- ---------------------------------------------------------------------
create table public.lectures (
  id             uuid        primary key default gen_random_uuid(),
  course_id      uuid        not null
                             references public.courses (id) on delete restrict,
  lecture_name   text        not null
                             constraint lectures_name_not_blank
                             check (char_length(btrim(lecture_name)) > 0),
  lecture_number integer     not null
                             constraint lectures_number_positive
                             check (lecture_number > 0),
  video_key      text        not null
                             constraint lectures_video_key_key unique,
  video_status   text        not null default 'uploaded'
                             constraint lectures_video_status_check
                             check (video_status in ('uploaded', 'processing', 'ready')),
  duration       integer
                             constraint lectures_duration_nonneg
                             check (duration is null or duration >= 0),
  is_hidden      boolean     not null default false,
  uploaded_by    uuid        not null
                             references public.profiles (id) on delete restrict,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  -- Deferrable so two lecture numbers can be swapped inside one transaction:
  --   begin;
  --   set constraints lectures_course_number_key deferred;
  --   ... update the numbers ...
  --   commit;
  -- Note: do not use INSERT ... ON CONFLICT against this constraint.
  constraint lectures_course_number_key
    unique (course_id, lecture_number)
    deferrable initially immediate
);

create trigger trg_lectures_updated_at
  before update on public.lectures
  for each row execute function public.set_updated_at();

-- Keep courses.lecture_count equal to the number of lectures that are
-- ready and not hidden.
create or replace function public.refresh_course_lecture_count()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    update public.courses c
       set lecture_count = (
             select count(*)::integer
               from public.lectures l
              where l.course_id = c.id
                and l.video_status = 'ready'
                and l.is_hidden = false
           )
     where c.id = old.course_id;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    update public.courses c
       set lecture_count = (
             select count(*)::integer
               from public.lectures l
              where l.course_id = c.id
                and l.video_status = 'ready'
                and l.is_hidden = false
           )
     where c.id = new.course_id;
  end if;

  return null;
end;
$$;

create trigger trg_lectures_refresh_course_count
  after insert or delete or update of course_id, video_status, is_hidden
  on public.lectures
  for each row execute function public.refresh_course_lecture_count();


-- ---------------------------------------------------------------------
-- 5. demo_lectures (standalone, free, no course)
-- ---------------------------------------------------------------------
create table public.demo_lectures (
  id            uuid        primary key default gen_random_uuid(),
  name          text        not null
                            constraint demo_lectures_name_not_blank
                            check (char_length(btrim(name)) > 0),
  description   text,
  thumbnail_url text,
  video_key     text        not null
                            constraint demo_lectures_video_key_key unique,
  duration      integer
                            constraint demo_lectures_duration_nonneg
                            check (duration is null or duration >= 0),
  is_published  boolean     not null default false,
  display_order integer     not null default 0,
  uploaded_by   uuid        not null
                            references public.profiles (id) on delete restrict,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index idx_demo_lectures_published_order
  on public.demo_lectures (is_published, display_order);

create trigger trg_demo_lectures_updated_at
  before update on public.demo_lectures
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 6. enrollments
-- ---------------------------------------------------------------------
create table public.enrollments (
  id         uuid        primary key default gen_random_uuid(),
  user_id    uuid        not null
                         references public.profiles (id) on delete restrict,
  course_id  uuid        not null
                         references public.courses (id) on delete restrict,
  status     text        not null default 'pending'
                         constraint enrollments_status_check
                         check (status in ('pending', 'paid', 'revoked')),
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- revoked_at is set exactly when status is 'revoked'
  constraint enrollments_revoked_at_consistent
    check ((status = 'revoked') = (revoked_at is not null))
);

-- One active (pending or paid) enrollment per student and course.
-- Any number of revoked rows are allowed.
create unique index uq_enrollments_one_active_per_user_course
  on public.enrollments (user_id, course_id)
  where status in ('pending', 'paid');

create index idx_enrollments_user_status
  on public.enrollments (user_id, status);

create index idx_enrollments_course_id
  on public.enrollments (course_id);

create trigger trg_enrollments_updated_at
  before update on public.enrollments
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 7. payments
-- ---------------------------------------------------------------------
create table public.payments (
  id                    uuid        primary key default gen_random_uuid(),
  user_id               uuid        not null
                                    references public.profiles (id) on delete restrict,
  enrollment_id         uuid        not null
                                    references public.enrollments (id) on delete restrict,
  razorpay_order_id     text        not null
                                    constraint payments_razorpay_order_id_key unique,
  razorpay_payment_id   text
                                    constraint payments_razorpay_payment_id_key unique,
  amount                integer     not null
                                    constraint payments_amount_positive check (amount > 0),
  currency              text        not null default 'INR'
                                    constraint payments_currency_inr check (currency = 'INR'),
  status                text        not null default 'created'
                                    constraint payments_status_check
                                    check (status in ('created', 'captured', 'failed', 'refunded')),
  failure_reason        text,
  paid_at               timestamptz,
  refund_eligible_until timestamptz,
  refunded_at           timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  constraint payments_paid_at_when_paid
    check (status not in ('captured', 'refunded') or paid_at is not null),
  constraint payments_refunded_at_when_refunded
    check (status <> 'refunded' or refunded_at is not null)
);

create index idx_payments_enrollment_id
  on public.payments (enrollment_id);

create index idx_payments_user_created
  on public.payments (user_id, created_at desc);

create index idx_payments_created_desc
  on public.payments (created_at desc);

create trigger trg_payments_updated_at
  before update on public.payments
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 8. payment_events (insert-only webhook log; no updated_at)
-- ---------------------------------------------------------------------
create table public.payment_events (
  payment_event_id   uuid        primary key default gen_random_uuid(),
  razorpay_event_id  text        not null,
  event_type         text        not null,  -- deliberately no check list
  payment_id         uuid
                                 references public.payments (id) on delete restrict,
  amount             integer
                                 constraint payment_events_amount_nonneg
                                 check (amount is null or amount >= 0),
  raw_payload        jsonb       not null,  -- never modified after insert
  signature_verified boolean     not null,
  processed          boolean     not null default false,
  error_note         text,
  received_at        timestamptz not null default now()
);

-- Event ids are unique only among signature-verified events, so a forged
-- event can never block a genuine one.
create unique index uq_payment_events_verified_event_id
  on public.payment_events (razorpay_event_id)
  where signature_verified = true;

create index idx_payment_events_payment_id
  on public.payment_events (payment_id);

-- Verified events still waiting to be processed (for retries).
create index idx_payment_events_unprocessed
  on public.payment_events (received_at)
  where processed = false and signature_verified = true;


-- ---------------------------------------------------------------------
-- 9. refund_requests
-- ---------------------------------------------------------------------
create table public.refund_requests (
  id                 uuid        primary key default gen_random_uuid(),
  payment_id         uuid        not null
                                 references public.payments (id) on delete restrict,
  user_id            uuid        not null
                                 references public.profiles (id) on delete restrict,
  course_id          uuid        not null
                                 references public.courses (id) on delete restrict,
  amount             integer     not null
                                 constraint refund_requests_amount_positive check (amount > 0),
  reason             text        not null
                                 constraint refund_requests_reason_len
                                 check (char_length(btrim(reason)) between 1 and 1000),
  status             text        not null default 'requested'
                                 constraint refund_requests_status_check
                                 check (status in ('requested', 'approved', 'rejected', 'processed', 'failed')),
  requested_at       timestamptz not null default now(),
  reviewed_by        uuid
                                 references public.profiles (id) on delete restrict,
  reviewed_at        timestamptz,
  admin_note         text,
  processed_at       timestamptz,
  razorpay_refund_id text
                                 constraint refund_requests_razorpay_refund_id_key unique,
  updated_at         timestamptz not null default now(),

  constraint refund_requests_review_fields_set
    check (status = 'requested'
           or (reviewed_by is not null and reviewed_at is not null))
);

-- One open request per payment. 'requested', 'approved' and 'failed' count
-- as open; 'rejected' and 'processed' free the payment.
create unique index uq_refund_requests_one_open_per_payment
  on public.refund_requests (payment_id)
  where status in ('requested', 'approved', 'failed');

create index idx_refund_requests_status_requested
  on public.refund_requests (status, requested_at);

create index idx_refund_requests_user_id
  on public.refund_requests (user_id);

create index idx_refund_requests_payment_id
  on public.refund_requests (payment_id);

create trigger trg_refund_requests_updated_at
  before update on public.refund_requests
  for each row execute function public.set_updated_at();


-- ---------------------------------------------------------------------
-- 10. Profile creation on signup
--     Role is ALWAYS 'student'. Nothing from user metadata can set it.
--     Phone is left empty: Google does not provide it.
-- ---------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
begin
  v_name := left(
    coalesce(
      nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(btrim(new.raw_user_meta_data ->> 'name'), ''),
      nullif(btrim(split_part(coalesce(new.email, ''), '@', 1)), ''),
      'Student'
    ),
    100
  );

  insert into public.profiles (id, user_name, email, role)
  values (new.id, v_name, lower(new.email), 'student');

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();


-- ---------------------------------------------------------------------
-- 11. Row Level Security: ON for every table, with NO policies.
--     The public (anon) key can read and write nothing. Only the backend,
--     using the service key, touches data. Do not add policies.
-- ---------------------------------------------------------------------
alter table public.profiles        enable row level security;
alter table public.teachers        enable row level security;
alter table public.courses         enable row level security;
alter table public.lectures        enable row level security;
alter table public.demo_lectures   enable row level security;
alter table public.enrollments     enable row level security;
alter table public.payments        enable row level security;
alter table public.payment_events  enable row level security;
alter table public.refund_requests enable row level security;
